// Offline cache so Ty's QR screen still works with no signal.
// Generated by tools/build.py: the version changes on every build.
var CACHE = "8kblends-bd079c6e91";
var PRECACHE = [
  "/",
  "/qr/",
  "/review/",
  "/book/",
  "/assets/friend.js?v=bd079c6e91",
  "/assets/review.js?v=bd079c6e91",
  "/assets/book.js?v=bd079c6e91",
  "/assets/site.css?v=bd079c6e91",
  "/assets/card.js?v=bd079c6e91",
  "/assets/fonts/oswald-latin-500-normal.woff2",
  "/assets/fonts/oswald-latin-600-normal.woff2",
  "/assets/fonts/mr-dafoe-latin-400-normal.woff2",
  "/assets/lightning.jpg",
  "/assets/barber-pole.webp",
  "/assets/avatar-standing.webp",
  "/icons/icon-192.png"
];

self.addEventListener("install", function (event) {
  event.waitUntil(
    caches.open(CACHE)
      .then(function (cache) { return cache.addAll(PRECACHE); })
      .then(function () { return self.skipWaiting(); })
  );
});

self.addEventListener("activate", function (event) {
  event.waitUntil(
    caches.keys()
      .then(function (keys) {
        return Promise.all(keys.filter(function (k) { return k !== CACHE; })
          .map(function (k) { return caches.delete(k); }));
      })
      .then(function () { return self.clients.claim(); })
  );
});

self.addEventListener("fetch", function (event) {
  var req = event.request;
  var url = new URL(req.url);
  // Leave the contact file alone so phones get it straight from the server.
  if (req.method !== "GET" || url.origin !== location.origin || url.pathname.endsWith(".vcf")) return;

  if (req.mode === "navigate") {
    // Pages: always try the network first so edits show up right away.
    event.respondWith(
      fetch(req).then(function (res) {
        var copy = res.clone();
        caches.open(CACHE).then(function (cache) { cache.put(req, copy); });
        return res;
      }).catch(function () {
        return caches.match(req).then(function (hit) { return hit || caches.match("/qr/"); });
      })
    );
    return;
  }

  event.respondWith(caches.match(req).then(function (hit) { return hit || fetch(req); }));
});
